mapper.select:
select count(*) from `game_taojiang_mahjong_record`
where `time` >= #{cutoff}
  and (`player_id0` = #{playerId}
   or `player_id1` = #{playerId}
   or `player_id2` = #{playerId}
   or `player_id3` = #{playerId})

select `id`, `venue_id` as venueId, `round_no` as roundNo, `banker`,
       `player_id0` as playerId0, `player_id1` as playerId1,
       `player_id2` as playerId2, `player_id3` as playerId3,
       `score0`, `score1`, `score2`, `score3`,
       `wingold0` as winGold0, `wingold1` as winGold1,
       `wingold2` as winGold2, `wingold3` as winGold3,
       `time`
from `game_taojiang_mahjong_record`
where `time` >= #{cutoff}
  and (`player_id0` = #{playerId}
   or `player_id1` = #{playerId}
   or `player_id2` = #{playerId}
   or `player_id3` = #{playerId})
order by `id` desc
limit #{offset}, #{pageSize}
